<?php
namespace App\Models\Ticket;
use App\Models\Channel\Channel; use App\Models\Concerns\HasPublicUuid; use App\Models\Customer\Company; use App\Models\Customer\Contact; use App\Models\Customer\CustomFieldValue; use App\Models\Customer\Tag; use App\Models\Inbox\Conversation; use App\Models\Team; use App\Models\User; use App\Models\AI\Suggestion; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\MorphToMany; use Illuminate\Database\Eloquent\SoftDeletes;
class Ticket extends Model { use HasPublicUuid,SoftDeletes; protected $fillable=['ticket_number','subject','description','contact_id','company_id','conversation_id','channel_id','team_id','assignee_id','priority','status_id','category_id','source','created_by','first_response_at','resolution_due_at','resolved_at','closed_at','sla_policy_id','merged_into_id','metadata']; protected function casts():array{return ['first_response_at'=>'datetime','resolution_due_at'=>'datetime','resolved_at'=>'datetime','closed_at'=>'datetime','metadata'=>'array'];} public function contact():BelongsTo{return $this->belongsTo(Contact::class);} public function company():BelongsTo{return $this->belongsTo(Company::class);} public function conversation():BelongsTo{return $this->belongsTo(Conversation::class);} public function channel():BelongsTo{return $this->belongsTo(Channel::class);} public function team():BelongsTo{return $this->belongsTo(Team::class);} public function assignee():BelongsTo{return $this->belongsTo(User::class,'assignee_id');} public function status():BelongsTo{return $this->belongsTo(TicketStatus::class,'status_id');} public function category():BelongsTo{return $this->belongsTo(TicketCategory::class);} public function creator():BelongsTo{return $this->belongsTo(User::class,'created_by');} public function comments():HasMany{return $this->hasMany(TicketComment::class);} public function activities():HasMany{return $this->hasMany(TicketActivity::class)->latest('occurred_at');} public function tags():MorphToMany{return $this->morphToMany(Tag::class,'taggable')->withPivot(['assigned_by','created_at']);} public function customFieldValues():HasMany{return $this->hasMany(CustomFieldValue::class,'resource_id')->where('resource_type','ticket');} public function aiSuggestions():HasMany{return $this->hasMany(Suggestion::class,'ticket_id');} }
